/**
 * Unit tests for JacksonAnnotationIntrospector#findContentDeserializer
 */
public class JacksonAnnotationIntrospector_findContentDeserializer_TriageGen2Test {

    private JacksonAnnotationIntrospector introspector;

    // Mock deserializer class for testing
    public static class MockDeserializer extends JsonDeserializer<Object> {
        @Override
        public Object deserialize(JsonParser p, com.fasterxml.jackson.databind.DeserializationContext ctxt) {
            return null;
        }
    }

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case where the Annotated object has no @JsonDeserialize annotation.
     * Expected: returns null.
     */
    @Test
    public void testFindContentDeserializer_NoAnnotation() {
        Annotated annotated = Mockito.mock(Annotated.class);
        // Since _findAnnotation is protected and used internally, we rely on the fact 
        // that if the annotation isn't present, the internal logic returns null.
        // We simulate this by providing an annotated object that doesn't return the annotation.

        // Note: In a real Jackson environment, _findAnnotation searches the annotation stack.
        // Since we cannot easily mock the protected _findAnnotation method without PowerMock,
        // we rely on the behavior that if no annotation is found, the result is null.

        // However, to trigger the 'ann != null' branch, we need to mock the behavior 
        // of the introspector's ability to find the annotation. 
        // Because we are testing the method itself, we provide a mock Annotated.

        Object result = introspector.findContentDeserializer(annotated);
        assertNull("Should return null when no annotation is present", result);
    }

    /**
     * Test case where @JsonDeserialize is present but contentUsing is JsonDeserializer.None.class.
     * Expected: returns null.
     */
    @Test
    public void testFindContentDeserializer_WithNoneAnnotation() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        // We need to simulate the internal _findAnnotation behavior.
        // Since we are testing the logic: if (deserClass != JsonDeserializer.None.class)
        // We'll use a spy to control the protected _findAnnotation method.
        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(JsonDeserializer.None.class);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertNull("Should return null when contentUsing is JsonDeserializer.None", result);
    }

    /**
     * Test case where @JsonDeserialize is present and contentUsing is a valid deserializer class.
     * Expected: returns the deserializer class.
     */
    @Test
    public void testFindContentDeserializer_WithValidDeserializer() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(MockDeserializer.class);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertEquals("Should return the deserializer class", MockDeserializer.class, result);
    }

    /**
     * Test case where @JsonDeserialize is present but contentUsing is null.
     * Expected: returns null.
     */
    @Test
    public void testFindContentDeserializer_WithNullContentUsing() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(null);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertNull("Should return null when contentUsing is null", result);
    }
}
